  });

  xtest('age on Venus', () => {
    expect(age('venus', 189839836)).toEqual(9.78);
  });

  xtest('age on Mars', () => {
    expect(age('mars', 2129871239)).toEqual(35.88);
  });

  xtest('age on Jupiter', () => {
    expect(age('jupiter', 901876382)).toEqual(2.41);
  });

  xtest('age on Saturn', () => {
